import{_ as a,o,c as i,a2 as r}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Buenas practicas MCP","description":"","frontmatter":{},"headers":[],"relativePath":"ia/mcp/07-buenas-practicas.md","filePath":"ia/mcp/07-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),l={name:"ia/mcp/07-buenas-practicas.md"};function s(n,e,t,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="buenas-practicas-mcp" tabindex="-1">Buenas practicas MCP <a class="header-anchor" href="#buenas-practicas-mcp" aria-label="Permalink to &quot;Buenas practicas MCP&quot;">​</a></h1><p>Recomendaciones para disenar, desplegar y operar servidores MCP en entornos de desarrollo y produccion.</p><h2 id="diseno-de-capacidades" tabindex="-1">Diseno de capacidades <a class="header-anchor" href="#diseno-de-capacidades" aria-label="Permalink to &quot;Diseno de capacidades&quot;">​</a></h2><ul><li><strong>Pocos tools bien definidos</strong> mejor que decenas solapadas.</li><li>Nombres con prefijo de dominio (<code>docs_</code>, <code>gh_</code>, <code>db_</code>).</li><li>Descripciones orientadas a cuando usar el tool (no solo que hace).</li><li>Resources para contenido grande; tools para busqueda y acciones.</li><li>Prompts para flujos estandar del equipo.</li></ul><h2 id="desarrollo" tabindex="-1">Desarrollo <a class="header-anchor" href="#desarrollo" aria-label="Permalink to &quot;Desarrollo&quot;">​</a></h2><ul><li>SDK oficial (<code>mcp</code>, <code>@modelcontextprotocol/sdk</code>).</li><li>Type hints / Pydantic para argumentos.</li><li>Tests unitarios de cada tool.</li><li><code>shellcheck</code> / lint en scripts de arranque.</li><li>Version semver y changelog.</li></ul><h2 id="despliegue-local" tabindex="-1">Despliegue local <a class="header-anchor" href="#despliegue-local" aria-label="Permalink to &quot;Despliegue local&quot;">​</a></h2><ul><li>Config MCP en repo (<code>.cursor/mcp.json</code> o doc en README interno).</li><li>Rutas absolutas o variables de entorno documentadas.</li><li>Pin de version en paquetes npm/pip.</li><li>stderr para logs; stdout reservado al protocolo en stdio.</li></ul><h2 id="despliegue-remoto" tabindex="-1">Despliegue remoto <a class="header-anchor" href="#despliegue-remoto" aria-label="Permalink to &quot;Despliegue remoto&quot;">​</a></h2><ul><li>TLS, autenticacion, rate limits.</li><li>Health endpoint.</li><li>Escalado horizontal con stateless servers cuando sea posible.</li><li>Monitoreo de latencia y errores por tool.</li></ul><h2 id="seguridad-resumen" tabindex="-1">Seguridad (resumen) <a class="header-anchor" href="#seguridad-resumen" aria-label="Permalink to &quot;Seguridad (resumen)&quot;">​</a></h2><ul><li>Read-only primero; escritura con aprobacion.</li><li>Validacion de argumentos en servidor.</li><li>Minimos privilegios OS y API tokens.</li><li>Auditoria de invocaciones.</li><li>Revision de resources de fuentes no confiables.</li></ul><h2 id="gobernanza-en-equipos" tabindex="-1">Gobernanza en equipos <a class="header-anchor" href="#gobernanza-en-equipos" aria-label="Permalink to &quot;Gobernanza en equipos&quot;">​</a></h2><ul><li>Catalogo interno de servidores aprobados.</li><li>Proceso para anadir nuevo MCP (security review).</li><li>Politica de datos: que repos pueden indexarse.</li><li>Rotacion de credenciales.</li></ul><h2 id="relacion-con-el-stack-del-repo" tabindex="-1">Relacion con el stack del repo <a class="header-anchor" href="#relacion-con-el-stack-del-repo" aria-label="Permalink to &quot;Relacion con el stack del repo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Manual</th></tr></thead><tbody><tr><td>Fundamentos RAG</td><td><a href="./../rag/01-introduccion-y-arquitectura">RAG</a></td></tr><tr><td>Agents y tools</td><td><a href="./../langchain/03-tools-y-agents">LangChain</a></td></tr><tr><td>Seguridad APIs</td><td><a href="./../../full-stack/arquitectura/apis-rest/06-seguridad">APIs REST</a></td></tr><tr><td>CI/CD</td><td><a href="./../../devops/cicd/01-introduccion-y-principios">CI/CD</a></td></tr></tbody></table><h2 id="checklist-servidor-listo-para-el-equipo" tabindex="-1">Checklist servidor listo para el equipo <a class="header-anchor" href="#checklist-servidor-listo-para-el-equipo" aria-label="Permalink to &quot;Checklist servidor listo para el equipo&quot;">​</a></h2><ul><li>[ ] Tools documentados con schemas validos</li><li>[ ] Path traversal / injection mitigados</li><li>[ ] Logs y errores claros en stderr</li><li>[ ] Tests automatizados</li><li>[ ] Config de ejemplo para Cursor/Claude</li><li>[ ] Version fijada en distribucion</li><li>[ ] Politica read-only o aprobaciones para escritura</li><li>[ ] Runbook si el proceso servidor falla</li></ul><h2 id="errores-que-veras-en-produccion" tabindex="-1">Errores que veras en produccion <a class="header-anchor" href="#errores-que-veras-en-produccion" aria-label="Permalink to &quot;Errores que veras en produccion&quot;">​</a></h2><ul><li>Modelo llama tool equivocado por descripcion ambigua.</li><li>Servidor caido y el chat falla sin mensaje claro al usuario.</li><li>Resource desactualizado respecto a fuente real (cache sin TTL).</li><li>Dos servidores que hacen lo mismo con resultados distintos.</li><li>Config MCP en laptop con rutas que no existen en otro OS.</li></ul><h2 id="cierre" tabindex="-1">Cierre <a class="header-anchor" href="#cierre" aria-label="Permalink to &quot;Cierre&quot;">​</a></h2><p>MCP convierte integraciones de IA en <strong>servicios composables</strong>. Combinado con <a href="./../rag/07-observabilidad-y-buenas-practicas">RAG</a> y <a href="./../langchain/07-despliegue-y-buenas-practicas">LangChain</a>, puedes ofrecer el mismo conocimiento y acciones en el IDE y en aplicaciones backend con un unico servidor bien disenado.</p>',22)])])}const m=a(l,[["render",s]]);export{h as __pageData,m as default};
